import{_ as t,o,c as s,a2 as d}from"./chunks/framework.CCXDMzJr.js";const g=JSON.parse('{"title":"第 2 章 仓库全景","description":"","frontmatter":{},"headers":[],"relativePath":"ch2-repo-layout.md","filePath":"ch2-repo-layout.md","lastUpdated":null}'),a={name:"ch2-repo-layout.md"};function c(i,e,n,l,r,p){return o(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="第-2-章-仓库全景" tabindex="-1">第 2 章 仓库全景 <a class="header-anchor" href="#第-2-章-仓库全景" aria-label="Permalink to &quot;第 2 章 仓库全景&quot;">​</a></h1><h2 id="_2-1-monorepo-概览" tabindex="-1">2.1 Monorepo 概览 <a class="header-anchor" href="#_2-1-monorepo-概览" aria-label="Permalink to &quot;2.1 Monorepo 概览&quot;">​</a></h2><p>deepseek-harness 是一个 pnpm workspace monorepo（<code>packageManager: pnpm@11.7.0</code>）。仓库顶层布局：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deepseek-harness/</span></span>
<span class="line"><span>├── apps/            # 应用：cli（命令行）、web（前端外壳）</span></span>
<span class="line"><span>├── packages/        # 全部业务包（约 50+ 个），按领域分组</span></span>
<span class="line"><span>├── vendor/          # 内嵌的第三方框架源码（cordis、cosmokit、loader、schemastery 等）</span></span>
<span class="line"><span>├── docs/            # 官方文档（架构、子系统、cookbook、用户指南，多语言）</span></span>
<span class="line"><span>├── examples/        # 可运行示例（web-cordis、headless-agent、mcp-memory、acp-agent、web-schedule）</span></span>
<span class="line"><span>├── scripts/         # 构建/校验/生成脚本（tsx 编写，150+ 个）</span></span>
<span class="line"><span>├── website/         # 官方文档站点（VitePress）</span></span>
<span class="line"><span>├── native/          # 原生模块</span></span>
<span class="line"><span>├── python/          # Python SDK 相关</span></span>
<span class="line"><span>├── assets/          # 静态资源</span></span>
<span class="line"><span>└── config/          # 部署配置与随附 agent-presets（位于 apps/cli/config）</span></span></code></pre></div><p>根 <code>package.json</code>（<code>@deepseek-ai/dsh-root</code>）定义了两大类脚本：</p><ul><li><strong>构建</strong>：<code>build:lib:host</code>（<code>tsc -b tsconfig.host.json &amp;&amp; tsdown --env.DSH_BUILD_FACE host</code>）、<code>build:lib:client</code>、<code>build:web</code>；</li><li><strong>校验</strong>：<code>typecheck</code>、<code>lint</code>、<code>test</code>、<code>test:e2e</code>、<code>hygiene</code>（knip/publint/constraints 等）、<code>doc-sync</code> 等，统由 <code>scripts/run-gates.ts</code> 编排成 CI 门禁。</li></ul><h2 id="_2-2-host-client-双聚合构建" tabindex="-1">2.2 Host / Client 双聚合构建 <a class="header-anchor" href="#_2-2-host-client-双聚合构建" aria-label="Permalink to &quot;2.2 Host / Client 双聚合构建&quot;">​</a></h2><p>仓库采用<strong>隔离的 Host 与 Client 两个 TypeScript 聚合</strong>（<code>docs/development.md</code>）：</p><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>tsconfig.host.json</code></td><td>Host 聚合：Host 包、examples、tests、scripts、website</td></tr><tr><td><code>tsconfig.client.json</code></td><td>Client 聚合：<code>packages/client/*</code>、<code>apps/web</code>、<code>api/remotes</code> 的 Client 半边</td></tr><tr><td><code>tsconfig.base.json</code></td><td>共享编译选项与 <code>paths</code> 源码映射（<strong>不</strong>含 <code>include</code>，作为解析门面）</td></tr><tr><td><code>tsconfig.base.client.json</code></td><td>浏览器编译设置（jsx、DOM libs）</td></tr></tbody></table><p>为什么必须分成两个程序？因为 Host 与 Client <strong>在同一 <code>Context</code> 接口上声明合并了不同的服务</strong>——两边在同一个 key 下合并出不同服务会让单个 <code>ts.Program</code> 报冲突。<code>docs/development.md</code> 明确写道：</p><blockquote><p>Host and Client stay two aggregate programs because both sides declaration-merge the cordis <code>Context</code> interface under the same keys with different services; one program seeing both merges reports a collision.</p></blockquote><p>这条约束派生出一系列纪律：新包必须且只能注册进一个聚合；脚本构建全仓库 <code>ts.Program</code> 时必须显式指定某个聚合；<code>api/remotes</code> 是唯一拆分的包（Host 入口参与 Typert 图，Client 入口消费生成的 <code>/remote</code> 声明）。</p><p>完整构建顺序（<code>docs/development.md</code>）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsconfig.host.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env.DSH_BUILD_FACE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Host 侧打包；Typert 只在这一步运行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsconfig.client.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env.DSH_BUILD_FACE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Client 侧打包（浏览器 bundle + Node loader）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:web</span></span></code></pre></div><p><strong>Typert</strong>（<code>packages/typert</code>）是仓库自研的类型反射工具：在 Host tsdown 阶段分析 Host 类型，生成两种产物——Host 自身反射目录（供 <code>ctx.remote</code> 运行时使用）与 <strong>Host-for-Client Remote 投影</strong>（供浏览器端类型化调用 Host）。这部分对应 <code>docs/api-gateway.md</code>，我们会在第 17 章详述。</p><h2 id="_2-3-包矩阵" tabindex="-1">2.3 包矩阵 <a class="header-anchor" href="#_2-3-包矩阵" aria-label="Permalink to &quot;2.3 包矩阵&quot;">​</a></h2><p><code>packages/</code> 下按领域分组的包（写作时快照）：</p><table tabindex="0"><thead><tr><th>分组</th><th>包</th><th>职责</th></tr></thead><tbody><tr><td><code>core/</code></td><td>session、tools、agent、agent-loop、agent-default-model、agent-tool-presentation、system-prompt、scope</td><td>事件溯源会话日志、工具注册表、Agent 接口、默认驱动、提示词组装、作用域原语</td></tr><tr><td><code>llm/</code></td><td>llm、llm-deepseek、llm-pi-ai、llm-retry、token-meter</td><td>消息/流式词汇、适配器接缝、具体适配器、重试策略</td></tr><tr><td><code>boot/</code></td><td>app-boot、cmdline、profile</td><td>启动组装、命令行服务</td></tr><tr><td><code>bundle/</code></td><td>base、web-app、headless</td><td>三种内置组合（Bundle）</td></tr><tr><td><code>host/</code></td><td>webserver、frontend-static、plugin-inventory、apiproxy、directory-picker-*</td><td>宿主进程侧的 Web 服务与浏览器资源托管</td></tr><tr><td><code>client/</code></td><td>runtime、connection、modules、web、web-react、locale、schema-form、ui-*（30+ 个 UI 包）</td><td>浏览器运行时与全部 UI</td></tr><tr><td><code>fs/</code></td><td>fs、fs-local、fs-observation-policy、fs-sandbox、tool-fs、tool-fs-search、tool-str-replace-editor</td><td>文件系统接缝三件套与工具</td></tr><tr><td><code>sandbox/</code>、<code>subprocess/</code>、<code>terminal/</code>、<code>shell/</code>、<code>jobs/</code></td><td>沙箱、子进程、终端、shell、后台作业接缝</td><td></td></tr><tr><td><code>skill/</code></td><td>skill、skill-badge、skill-filesystem、tool-skill</td><td>技能系统</td></tr><tr><td><code>goal/</code></td><td>goal、command-goal、tool-goal、goal-round-driver</td><td>目标系统</td></tr><tr><td><code>subagent/</code></td><td>subagent、subagent-acp、subagent-claude-code 等</td><td>子代理接缝与多后端</td></tr><tr><td><code>preset/</code></td><td>agent-presets</td><td>代理预设（per-agent 能力组合）</td></tr><tr><td><code>session/</code></td><td>session-query、session-projection、session-reference、session-title、session-telemetry</td><td>会话查询/投影/标题/遥测</td></tr><tr><td><code>api/</code></td><td>remotes</td><td>Host↔Client 类型化 RPC</td></tr><tr><td>其他</td><td>acp、attachment、code-runtime、compaction、context、credentials、feedback、guard、hooks、identity、interaction、lsp、mcp、plan、runtime-diagnostics、sdk、schedule、settings、spill、storage、todo、typert、util/<em>、web、workflow、workspace、extensions/</em>、test-support</td><td>各自领域能力</td></tr></tbody></table><p>包之间以 <code>peerDependencies</code> 表达运行时依赖；<code>docs/module-graph.md</code> 用 mermaid 生成了完整的包级依赖图（由 <code>scripts/gen-module-graph.ts</code> 维护，构建期有 <code>verify-module-graph</code> 门禁）。</p><h2 id="_2-4-文档体系" tabindex="-1">2.4 文档体系 <a class="header-anchor" href="#_2-4-文档体系" aria-label="Permalink to &quot;2.4 文档体系&quot;">​</a></h2><p><code>docs/</code> 是仓库中极其重要的资产，它本身构成一份高质量的架构文档集：</p><ul><li><code>architecture.md</code>（+ <code>.zh.md</code>）：总架构，阅读任何 <code>packages/</code> 代码前的必读；</li><li><code>cordis-primer.md</code> / <code>cordis-tutorial/</code>：Cordis 入门与教程；</li><li><code>subsystems/*.md</code>：每个子系统的深度文档，内含 <strong>type-equiv</strong> 代码块（从源码逐字抽取的类型声明 + JSDoc，由 <code>verify-type-equiv</code> 门禁保证与源码同步）；</li><li><code>cookbook/</code>：扩展 cookbook（加包、加工具、加 LLM 适配器、加对话节点）；</li><li><code>config-catalog.md</code>：生成的配置目录（composition 行字段大全）；</li><li><code>event-producer-consumer.md</code>、<code>tool-catalog.md</code>、<code>persistence-catalog.md</code>：生成的事件/工具/持久化目录；</li><li><code>agent-lifecycle.md</code>、<code>tool-execution-pipeline.md</code>：时序图与管道说明；</li><li><code>api-gateway.md</code>、<code>capability-seams.md</code>、<code>glossary.md</code>、<code>defensive-patterns.md</code> 等。</li></ul><p>这些文档大多有官方中文版（<code>.zh.md</code>），与源码通过 <code>doc-sync</code> 门禁保持同步，是本书写作的重要一手依据。本书尽量<strong>独立</strong>从源码出发做解析，官方文档用于交叉验证。</p><h2 id="_2-5-代码规约与工程实践" tabindex="-1">2.5 代码规约与工程实践 <a class="header-anchor" href="#_2-5-代码规约与工程实践" aria-label="Permalink to &quot;2.5 代码规约与工程实践&quot;">​</a></h2><p>几个值得注意的工程纪律（源码中处处体现）：</p><ol><li><strong>三个 TODO 标记的急迫性分级</strong>：<code>FIXME</code>（应阻塞发布）&gt; <code>TODO</code>（应尽快修复）&gt; <code>XXX</code>（可能某天修复）；</li><li><strong>品牌化 ID（Branded ID）</strong>：跨包传递的 ID（<code>SessionId</code>、<code>CallId</code>、<code>JobId</code>）在类型层面不可互换，见 <code>packages/util/brand</code>；</li><li><strong><code>Map → 派生联合</code>模式</strong>：几乎每个可扩展联合类型都写成 <code>interface XxxMap</code> + <code>keyof</code> 派生，插件通过 <strong>declaration merging</strong> 扩展，无需改动源码包；</li><li><strong>不可变与冻结</strong>：会话事件在写入时深冻结（deep-freeze），保证日志不可被篡改；</li><li><strong>i18n 配对</strong>：中英文档通过 <code>.i18n.yaml</code> 配对 + Git merge driver 自动同步；</li><li><strong>Agent Notes</strong>：<code>.agents/notes/</code> 存放按分类归档的设计决策笔记（implemented/architecture、bug-fix、simplification 等），是理解&quot;为什么&quot;的一手资料。</li></ol><h2 id="_2-6-测试与-ci" tabindex="-1">2.6 测试与 CI <a class="header-anchor" href="#_2-6-测试与-ci" aria-label="Permalink to &quot;2.6 测试与 CI&quot;">​</a></h2><ul><li>单元/集成：<code>vitest</code>（<code>vitest.config.ts</code>），覆盖到几乎所有包；</li><li>Web 测试：<code>vitest.web.config.ts</code>（基于构建产物）；</li><li>快照测试：<code>DSH_SNAPSHOT=record|refresh|replay</code> 三种模式；</li><li>e2e：真实 API 测试（未设置 <code>DEEPSEEK_API_KEY</code> 时自跳过）；</li><li>CI：<code>.github/workflows/ci.yml</code> 将门禁分组到宽车道，由 <code>scripts/run-gates.ts</code> 驱动；Node 兼容矩阵覆盖 22.19 / 24 / 26；</li><li>Windows：<code>check:windows-*</code> 系列门禁（含 Wine 方案）。</li></ul><p>下一章进入总架构：理解&quot;一切皆插件&quot;如何在 Cordis 上成立。</p>`,29)])])}const m=t(a,[["render",c]]);export{g as __pageData,m as default};
